{
  "scenarios": [
    {
      "id": "posting-positive-01",
      "operation": {
        "method": "POST",
        "path": "/posting-runs"
      },
      "category": "positive",
      "purpose": "Representar um registro estruturado válido pelo schema, sem pressupor aprovação nas consultas aos arquivos persistentes.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "dailyTransactions": [
            {
              "transactionId": "T1",
              "typeCode": "01",
              "categoryCode": "0005",
              "source": "System",
              "description": "",
              "amount": "1.00",
              "merchantId": "000000000",
              "merchantName": "",
              "merchantCity": "",
              "merchantZip": "",
              "cardNumber": "A",
              "originalTimestamp": "",
              "processingTimestamp": ""
            }
          ],
          "transactionFile": "TRANFILE",
          "crossReferenceFile": "XREFFILE",
          "accountFile": "ACCTFILE",
          "categoryBalanceFile": "TCATBALF",
          "rejectFile": "DALYREJS"
        }
      },
      "expectedFromContract": {
        "requestSchema": "O corpo satisfaz o schema da operação; cartão não numérico e timestamps vazios são representáveis.",
        "responses": {
          "200": {
            "schema": "#/components/schemas/PostingResult",
            "obligations": [
              "Na conclusão normal, transactionsProcessed é 1.",
              "Rejeições de negócio são compatíveis com HTTP 200; havendo rejeições, returnCode é definido como 4.",
              "Um registro aprovado tem processingTimestamp substituído pelo timestamp do runtime."
            ]
          },
          "500": {
            "schema": "#/components/schemas/ExecutionFailure",
            "obligations": [
              "É o mapeamento documentado para falha de execução; efeitos anteriores podem permanecer."
            ]
          }
        }
      },
      "limitations": [
        "Os identificadores de arquivos são candidatos opacos derivados dos nomes do contrato, não fixtures nem recursos comprovadamente provisionados.",
        "Não se pressupõe existência do cartão, da conta ou de saldos; aprovação, rejeição específica e sucesso de execução não são determinados pelo request.",
        "Não se fixa timestamp, conteúdo de filler ou returnCode zero."
      ]
    },
    {
      "id": "posting-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/posting-runs"
      },
      "category": "boundary",
      "purpose": "Exercitar o limite inferior representável do arquivo sequencial diário: nenhum registro.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "dailyTransactions": [],
          "transactionFile": "TRANFILE",
          "crossReferenceFile": "XREFFILE",
          "accountFile": "ACCTFILE",
          "categoryBalanceFile": "TCATBALF",
          "rejectFile": "DALYREJS"
        }
      },
      "expectedFromContract": {
        "requestSchema": "dailyTransactions permite array vazio.",
        "responses": {
          "200": {
            "schema": "#/components/schemas/PostingResult",
            "obligations": [
              "Na conclusão normal, transactionsProcessed e transactionsRejected são zero; writtenTransactions e rejects estão vazios.",
              "O contrato não exige returnCode zero."
            ]
          },
          "500": {
            "schema": "#/components/schemas/ExecutionFailure",
            "obligations": [
              "Entrada vazia não elimina possíveis falhas de abertura ou fechamento dos arquivos."
            ]
          }
        }
      },
      "limitations": [
        "Bindings são identificadores candidatos sem garantia de resolução.",
        "TRANFILE e DALYREJS são abertos OUTPUT mesmo sem registros; não se promete preservação do conteúdo anterior."
      ]
    },
    {
      "id": "posting-negative-01",
      "operation": {
        "method": "POST",
        "path": "/posting-runs"
      },
      "category": "negative",
      "purpose": "Representar um corpo que omite todas as propriedades obrigatórias.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {}
      },
      "expectedFromContract": {
        "requestSchema": "Inválido: faltam dailyTransactions, transactionFile, crossReferenceFile, accountFile, categoryBalanceFile e rejectFile.",
        "obligations": [
          "O contrato exige essas seis propriedades."
        ],
        "statusConstraint": "Não há status nem schema de resposta especificados para rejeição de request inválido."
      },
      "limitations": [
        "Candidato deliberadamente inválido pelo schema.",
        "Não se infere HTTP 400, 422 ou 500 nem execução do programa para esse corpo."
      ]
    },
    {
      "id": "interest-positive-01",
      "operation": {
        "method": "POST",
        "path": "/interest-runs"
      },
      "category": "positive",
      "purpose": "Usar o prefixo exemplificado no contrato e omitir parameterLength para exercitar seu default.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "parameterDate": "2022071800",
          "categoryBalanceFile": "TCATBALF",
          "crossReferenceFile": "XREFFILE",
          "disclosureGroupFile": "DISCGRP",
          "accountFile": "ACCTFILE",
          "outputTransactionFile": "TRANSACT"
        }
      },
      "expectedFromContract": {
        "requestSchema": "Corpo válido; parameterDate tem exatamente dez caracteres.",
        "obligations": [
          "O transporte fornece parameterLength igual a 10 quando omitido."
        ],
        "responses": {
          "200": {
            "schema": "#/components/schemas/InterestResult",
            "obligations": [
              "generatedTransactions e diagnostics são obrigatórios.",
              "Se houver transações geradas, seus identificadores concatenam o prefixo com contador de seis dígitos iniciado em 000001.",
              "A saída é separada do transaction master; a operação não atualiza category balances."
            ]
          },
          "500": {
            "schema": "#/components/schemas/ExecutionFailure",
            "obligations": [
              "Falhas de execução podem deixar efeitos persistentes e saída parcial."
            ]
          }
        }
      },
      "limitations": [
        "Bindings são identificadores candidatos derivados do contrato, não fixtures.",
        "O request não fornece conteúdo de categorias, taxas, contas ou referências; quantidade e valores gerados não são predetermináveis.",
        "A disponibilidade do índice alternativo por conta depende do ambiente."
      ]
    },
    {
      "id": "interest-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/interest-runs"
      },
      "category": "boundary",
      "purpose": "Combinar o mínimo de parameterLength com prefixo textual de dez caracteres, sem interpretação de calendário.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "parameterDate": "ABCDEFGHIJ",
          "parameterLength": -32768,
          "categoryBalanceFile": "TCATBALF",
          "crossReferenceFile": "XREFFILE",
          "disclosureGroupFile": "DISCGRP",
          "accountFile": "ACCTFILE",
          "outputTransactionFile": "TRANSACT"
        }
      },
      "expectedFromContract": {
        "requestSchema": "Corpo válido: -32768 é o mínimo inclusivo e texto arbitrário de comprimento dez é permitido.",
        "obligations": [
          "O programa não inspeciona parameterLength nem interpreta parameterDate como data."
        ],
        "responses": {
          "200": {
            "schema": "#/components/schemas/InterestResult",
            "obligations": [
              "Se uma primeira transação for gerada, seu identificador será ABCDEFGHIJ000001."
            ]
          },
          "500": {
            "schema": "#/components/schemas/ExecutionFailure"
          }
        }
      },
      "limitations": [
        "Não há garantia de resolução dos bindings nem de existência de registros que produzam transações.",
        "O limite do parâmetro não permite selecionar taxas, contas ou caminhos de execução."
      ]
    },
    {
      "id": "interest-boundary-02",
      "operation": {
        "method": "POST",
        "path": "/interest-runs"
      },
      "category": "boundary",
      "purpose": "Representar o máximo inclusivo de parameterLength.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "parameterDate": "2022071800",
          "parameterLength": 32767,
          "categoryBalanceFile": "TCATBALF",
          "crossReferenceFile": "XREFFILE",
          "disclosureGroupFile": "DISCGRP",
          "accountFile": "ACCTFILE",
          "outputTransactionFile": "TRANSACT"
        }
      },
      "expectedFromContract": {
        "requestSchema": "Corpo válido: 32767 é o máximo inclusivo de parameterLength.",
        "obligations": [
          "parameterLength não é inspecionado pelo programa."
        ],
        "responses": {
          "200": {
            "schema": "#/components/schemas/InterestResult"
          },
          "500": {
            "schema": "#/components/schemas/ExecutionFailure"
          }
        }
      },
      "limitations": [
        "Bindings não designam fixtures conhecidas.",
        "Não se pressupõem resultados iguais aos de outra invocação: recursos são persistentes e timestamps dependem do runtime."
      ]
    },
    {
      "id": "interest-negative-01",
      "operation": {
        "method": "POST",
        "path": "/interest-runs"
      },
      "category": "negative",
      "purpose": "Violar apenas o comprimento mínimo do prefixo obrigatório.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "parameterDate": "202207180",
          "categoryBalanceFile": "TCATBALF",
          "crossReferenceFile": "XREFFILE",
          "disclosureGroupFile": "DISCGRP",
          "accountFile": "ACCTFILE",
          "outputTransactionFile": "TRANSACT"
        }
      },
      "expectedFromContract": {
        "requestSchema": "Inválido: parameterDate possui nove caracteres, mas exige exatamente dez.",
        "statusConstraint": "O contrato não especifica resposta HTTP para violação do schema de entrada."
      },
      "limitations": [
        "Candidato deliberadamente inválido no transporte, embora o programa não valide o comprimento.",
        "Não se presume preenchimento automático do prefixo, rejeição com status específico ou execução COBOL."
      ]
    },
    {
      "id": "report-positive-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "positive",
      "purpose": "Representar transação estruturada com DATEPARM vazio, caso explicitamente aceito que produz relatório vazio na conclusão normal.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [
            {
              "transactionId": "T1",
              "typeCode": "01",
              "categoryCode": "0005",
              "source": "System",
              "description": "",
              "amount": "0.00",
              "merchantId": "000000000",
              "merchantName": "",
              "merchantCity": "",
              "merchantZip": "",
              "cardNumber": "A",
              "originalTimestamp": "",
              "processingTimestamp": ""
            }
          ],
          "dateParameterRecords": [],
          "crossReferenceFile": "CARDXREF",
          "transactionTypeFile": "TRANTYPE",
          "transactionCategoryFile": "TRANCATG",
          "reportFile": "TRANREPT"
        }
      },
      "expectedFromContract": {
        "requestSchema": "Corpo válido; DATEPARM vazio é expressamente representável.",
        "responses": {
          "200": {
            "schema": "#/components/schemas/ReportResult",
            "obligations": [
              "DATEPARM vazio define EOF e produz lines vazio.",
              "diagnostics é obrigatório e contém strings."
            ]
          },
          "500": {
            "schema": "#/components/schemas/ExecutionFailure",
            "obligations": [
              "Falhas de execução continuam possíveis, inclusive nas aberturas de arquivos."
            ]
          }
        },
        "obligations": [
          "A operação não modifica contas, referências de cartão ou transaction master."
        ]
      },
      "limitations": [
        "Bindings são candidatos opacos, não arquivos provisionados.",
        "Este caso não cobre detalhes, paginação ou consultas de registros incluídos.",
        "Não se fixa o conteúdo de diagnostics."
      ]
    },
    {
      "id": "report-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "boundary",
      "purpose": "Representar simultaneamente os limites inferiores dos dois arquivos sequenciais fornecidos pelo chamador.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameterRecords": [],
          "crossReferenceFile": "CARDXREF",
          "transactionTypeFile": "TRANTYPE",
          "transactionCategoryFile": "TRANCATG",
          "reportFile": "TRANREPT"
        }
      },
      "expectedFromContract": {
        "requestSchema": "Ambos os arrays podem estar vazios.",
        "responses": {
          "200": {
            "schema": "#/components/schemas/ReportResult",
            "obligations": [
              "Com DATEPARM vazio, o relatório é vazio: lines não contém registros.",
              "diagnostics permanece obrigatório."
            ]
          },
          "500": {
            "schema": "#/components/schemas/ExecutionFailure"
          }
        }
      },
      "limitations": [
        "O ambiente ainda precisa resolver e abrir os arquivos vinculados.",
        "Não se extrapola esse resultado para transactions vazio com DATEPARM não vazio, caso sujeito às incertezas de EOF documentadas.",
        "TRANREPT é aberto OUTPUT; relatório vazio não implica preservação da saída anterior."
      ]
    },
    {
      "id": "report-negative-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "negative",
      "purpose": "Fornecer registro DATEPARM contendo apenas as posições usadas para datas, mas sem a largura obrigatória de 80 caracteres.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameterRecords": [
            "2022-07-18 2022-07-18"
          ],
          "crossReferenceFile": "CARDXREF",
          "transactionTypeFile": "TRANTYPE",
          "transactionCategoryFile": "TRANCATG",
          "reportFile": "TRANREPT"
        }
      },
      "expectedFromContract": {
        "requestSchema": "Inválido: o registro tem 21 caracteres; cada item de dateParameterRecords deve ter exatamente 80.",
        "statusConstraint": "Não há status ou schema de resposta definidos para esse erro de entrada."
      },
      "limitations": [
        "Candidato deliberadamente inválido; não se presume padding de DATEPARM pelo transporte.",
        "Não se infere resposta 400, 422 ou 500.",
        "Nenhuma operação foi executada; os casos gerados não constituem cobertura exaustiva do contrato."
      ]
    }
  ]
}
